function hasCycle(head: ListNode | null): boolean {
  // Черепаха шагает на 1 узел, заяц — на 2
  let slow = head;
  let fast = head;

  // Если цикла нет, заяц рано или поздно упрётся в null
  while (fast !== null && fast.next !== null) {
    slow = slow!.next;
    fast = fast.next.next;

    // Заяц догнал черепаху «по кругу» — значит, цикл есть
    if (slow === fast) {
      return true;
    }
  }

  // Дошли до конца списка — цикла нет
  return false;
}

// Время: O(n) — внутри цикла заяц догоняет черепаху не более чем за длину цикла
// Память: O(1) — только два указателя
